// Fight choreographies recorded from the original's fight engine ($03:88B3) running in
// research/emu.py (research/fight3.py captures, extracted per frame from OAM). Generated; the
// scene (fightscene.js) replays them. Coordinates are for the attacker on the left, as the
// original always draws it; the scene mirrors them (x' = 255 - size - x) for an attacker on the
// right. Nothing here is ROM data: only sprite positions, tile numbers and timings.
//
// Track: 'frame,size,row:x,y,tile,flags tok tok ...', one entry per frame from `frame` on;
//   tok = [n*]dx,dy[,tile,flags] (n frames with the same step; tile/flags change when given),
//   flags bit 0 = h-flip, bit 1 = v-flip; row = OBJ palette row (0-2 attacker, 3-5 defender).
// Body track (melee): '=x,y,tile,flags' sets the position, 'h' = not on screen that frame.

// Capital ships and structures attacking: "type/weapon slot/target" (c = small craft,
// s = ship). hull = the attacker's hull sprites (the last state holds), fx = shots and flashes,
// hit = explosions and debris on the target; fire / boom = first shot / hit frame, bob = frame the
// target ship starts to rock, black = frame the screen has faded out; R / Rfx = bodies and
// effects of small craft that strike back and charge (melee weapons, as in MELEE).
